// Parse Instagram Messenger webhook payload
// Instagram sends DMs via the Messenger API
const body = $input.first().json.body || $input.first().json;

// Handle webhook verification challenge
if (body['hub.challenge']) {
  return [{ json: { challenge: body['hub.challenge'], isVerification: true } }];
}

// Extract DM data from Instagram webhook
const entries = body.entry || [];
const messages = [];

for (const entry of entries) {
  const messaging = entry.messaging || [];
  for (const msg of messaging) {
    if (msg.message && msg.message.text) {
      messages.push({
        senderId: msg.sender.id,
        recipientId: msg.recipient.id,
        messageText: msg.message.text,
        messageId: msg.message.mid,
        timestamp: msg.timestamp,
        isVerification: false
      });
    }
  }
}

if (messages.length === 0) {
  // Could be a delivery/read receipt — skip
  return [{ json: { skip: true, reason: 'No text message found' } }];
}

return messages.map(m => ({ json: m }));

// Detect keyword in DM and select the right auto-response
const msg = $input.first().json;
const text = (msg.messageText || '').toUpperCase().trim();

// Keyword → response mapping
const keywordMap = [
  {
    keywords: ['BUILD', 'CONSTRUIR', 'QUIERO CONSTRUIR', 'WANT TO BUILD'],
    responseKey: 'build',
    label: 'BUILD keyword'
  },
  {
    keywords: ['GUIDE', 'GUIA', 'CHECKLIST', 'LISTA'],
    responseKey: 'guide',
    label: 'GUIDE keyword'
  },
  {
    keywords: ['TULUM'],
    responseKey: 'tulum',
    label: 'TULUM keyword'
  },
  {
    keywords: ['INVESTOR', 'INVERSION', 'INVERSIÓN', 'INVEST'],
    responseKey: 'investor',
    label: 'INVESTOR keyword'
  },
  {
    keywords: ['CARPENTRY', 'CARPINTERIA', 'CARPINTERÍA', 'MUEBLES', 'FURNITURE'],
    responseKey: 'carpentry',
    label: 'CARPENTRY keyword'
  },
  {
    keywords: ['PRICE', 'PRECIO', 'COSTO', 'COST', 'QUOTE', 'COTIZACION', 'COTIZACIÓN', 'CUANTO', 'CUÁNTO'],
    responseKey: 'price',
    label: 'PRICE keyword'
  },
  {
    keywords: ['HOLA', 'HELLO', 'HI', 'BUENOS DIAS', 'BUENOS DÍAS', 'GOOD MORNING'],
    responseKey: 'greeting',
    label: 'Greeting'
  }
];

let matched = null;
for (const entry of keywordMap) {
  if (entry.keywords.some(k => text.includes(k))) {
    matched = entry;
    break;
  }
}

// Responses
const responses = {
  build: `Hi! 👋 Thanks for reaching out to RECREA Construcción!\n\nWe've been building villas, homes, and commercial spaces in the Riviera Maya for 18 years — 196 completed projects and counting.\n\nTo send you the right info, could you tell us:\n📍 Where is your land? (Tulum, Playa, Cancún, Puerto Aventuras?)\n🏡 What do you want to build?\n📐 Approximate size or budget?\n\nWe'll get back to you with a full breakdown — no commitment needed! 🙌`,

  guide: `Thanks for your interest! 📋\n\nWe're sending you our FREE Investor Checklist right now:\n\n✅ 10 questions to ask before hiring a contractor in Mexico\n✅ Permit timeline and costs breakdown\n✅ Materials guide for tropical climate\n✅ Budget calculator template\n\n👉 Full guide: construction-recrea.com/mx/guide\n\nAny specific questions? Just reply here — we love helping investors! 🏗️`,

  tulum: `Tulum is one of our favorite areas to build! 🌴\n\nWe've completed multiple projects in the Tulum corridor — from the hotel zone to jungle lots near the biosphere reserve.\n\nTo give you the best info for your Tulum project:\n📐 What are your lot dimensions?\n🏡 What type of project? (Villa, renovation, commercial?)\n📅 When are you thinking of starting?\n\nDM us the details and we'll prepare a free estimate! 🏗️`,

  investor: `Welcome! You've come to the right place. 🌎\n\n85% of our clients are foreign investors — we know exactly how to make building in Mexico smooth and stress-free.\n\nHere's what we offer international investors:\n✅ Full bilingual communication\n✅ Weekly video/photo updates\n✅ We handle ALL permits and paperwork\n✅ Transparent fixed-price contracts\n✅ 18 years of experience in Riviera Maya\n\nWant to start with a free consultation? Tell us about your project! 📲`,

  carpentry: `Our carpentry team is one of the best in the Riviera Maya! 🪵✨\n\nWe do 100% in-house custom work:\n🚪 Custom doors and frames\n🛋️ Built-in furniture\n🍽️ Kitchen cabinetry\n🪞 Walk-in closets\n🪟 Custom windows\n\nWe'd love to show you our portfolio. What type of project are you working on?\n\n👉 See examples: construction-recrea.com/mx/carpentry`,

  price: `Great question! Construction costs in the Riviera Maya depend on several factors:\n\n📐 Size (m²)\n📍 Location\n🏗️ Project type\n✨ Finish level\n\nRough ranges (USD):\n• Standard residential: from $800/m²\n• Mid-range villa: $1,200–$1,800/m²\n• Luxury finishes: $2,000+/m²\n\nSend us your project details and we'll give you a real estimate within 48h — no commitment needed! 👍`,

  greeting: `Hola! 👋 Welcome to RECREA Construcción!\n\nWe're a full-service construction company with 18 years in the Riviera Maya, Mexico.\n\nWe specialize in:\n🏡 Luxury villas and residences\n🏢 Commercial spaces\n🔨 Full renovations\n\nHow can we help you? Tell us about your project! 🏗️\n\n(Or type one of these: BUILD / PRICE / TULUM / GUIDE)`
};

const defaultResponse = `Hi! Thanks for messaging RECREA Construcción. 👋\n\nWe build luxury villas and commercial spaces in the Riviera Maya for 18 years.\n\nOur team will get back to you shortly! In the meantime, tell us about your project:\n📍 Location\n🏡 Type of build\n📐 Size / budget\n\nOr visit: construction-recrea.com/mx`;

const responseText = matched ? responses[matched.responseKey] : defaultResponse;
const responseKey = matched ? matched.responseKey : 'default';
const label = matched ? matched.label : 'No keyword matched';

return [
  {
    json: {
      senderId: msg.senderId,
      originalMessage: msg.messageText,
      responseText: responseText,
      responseKey: responseKey,
      matchedLabel: label,
      timestamp: msg.timestamp
    }
  }
];
